    constructor(size = 7) {
        this.size = size;
        this.table = new Array(size).fill(null);
    }
    
    _hash(key) {
        let sum = 0;
        for (let i = 0; i < key.length; i++) {
            sum += key.charCodeAt(i);
        }
        return sum % this.size;
    }
    
    insert(key) {
        const index = this._hash(key);
        this.table[index] = key;
    }
    
